import React, { useState } from 'react';
import { ComponentMeta, ComponentStory } from '@storybook/react';
import { ProgressTracker, useProgressTracker, Button, Paragraph } from '../..';

export default {
  title: 'General/ProgressTracker/Root',
  component: ProgressTracker.Root,
  argTypes: {
    orientation: {
      description:
        'The stepper orientation( layout flow direction). Is passed to child components.',
      defaultValue: 'horizontal',
    },
    size: {
      description: 'The size of the component children. Is passed to child components.',
      defaultValue: 'large',
    },
    currentStep: {
      description: 'Set the active step (zero based index). Is passed to child components.',
      defaultValue: 0,
    },
  },
  parameters: {
    docs: {
      description: {
        component:
          'The `ProgressTracker.Root` is the root component of ProgressTracker. It controls the global context of ProgressTracker. <br><br>The `ProgressTracker.Root` should be used with the `ProgressTracker.Header` as subcomponent.  <br><br>How to install: `yarn add @hexa-ui/components`<br><br>How to import: `import { ProgressTracker } from "@hexa-ui/components"`<br><br>How to use: `ProgressTracker.Root`, `ProgressTracker.Header`, `ProgressTracker.Step` and `ProgressTracker.StepLabel` or destructure it `{ Root, Header, Step, StepLabel } = ProgressTracker`',
      },
    },
  },
} as ComponentMeta<typeof ProgressTracker.Root>;

const Template: ComponentStory<typeof ProgressTracker.Root> = (args) => {
  const array = ['a', 'b', 'c', 'd'];
  return (
    <>
      <ProgressTracker.Root {...args}>
        <ProgressTracker.Header>
          {array.map((item, index) => (
            <ProgressTracker.Step index={index} key={item}>
              <ProgressTracker.StepLabel
                alertMessage={`alert error for Step ${index}`}
                label={`Step ${index + 1} item ${item}`}
                detail="Detail"
              />
            </ProgressTracker.Step>
          ))}
        </ProgressTracker.Header>
      </ProgressTracker.Root>
    </>
  );
};

export const defaultProgressTracker = Template.bind({});

export const LinearProgressTracker: ComponentStory<typeof ProgressTracker.Root> = () => {
  const [completedSteps, setCompletedSteps] = useState<number[]>([]);
  const array = ['a', 'b', 'c', 'd'];
  const { currentStep, goToNext, goToPrevious, reset } = useProgressTracker({
    initialStep: 0,
    stepQuantity: array.length,
  });
  const [biggestStepActive, setBiggestStepActive] = useState<number>(currentStep);
  return (
    <>
      <ProgressTracker.Root size="large" orientation="horizontal" currentStep={currentStep}>
        <ProgressTracker.Header>
          {array.map((item, index) => (
            <ProgressTracker.Step
              index={index}
              key={item}
              completed={completedSteps.includes(index)}
              disabled={index > biggestStepActive && !completedSteps.includes(index)}
            >
              <ProgressTracker.StepLabel
                alertMessage={`alert error for Step ${index}`}
                label={`Step ${index + 1} item ${item}`}
                detail="Detail"
              />
            </ProgressTracker.Step>
          ))}
        </ProgressTracker.Header>
      </ProgressTracker.Root>
      <Paragraph css={{ marginBottom: 12, marginTop: 12 }} alignment="center">
        Current Step {currentStep + 1}
      </Paragraph>
      <div style={{ display: 'flex', flexDirection: 'row', justifyContent: 'space-evenly' }}>
        <Button
          onClick={() => {
            reset();
            setBiggestStepActive(0);
            setCompletedSteps([]);
          }}
        >
          Reset
        </Button>
        <Button
          disabled={currentStep === 0}
          onClick={() => {
            setCompletedSteps(completedSteps.filter((step) => step !== currentStep - 1));
            goToPrevious();
          }}
        >
          Previous
        </Button>
        <Button
          disabled={currentStep >= array.length}
          onClick={() => {
            const nextStep = currentStep + 1;
            setCompletedSteps([...completedSteps, currentStep]);
            if (nextStep > biggestStepActive) {
              setBiggestStepActive(nextStep);
            }
            goToNext();
          }}
        >
          Next
        </Button>
      </div>
    </>
  );
};

export const NoLinearProgressTracker: ComponentStory<typeof ProgressTracker.Root> = () => {
  const [completedSteps, setCompletedSteps] = useState<number[]>([]);
  const array = ['a', 'b', 'c', 'd'];
  const { currentStep, goTo, goToPrevious, goToNext, reset } = useProgressTracker({
    initialStep: 0,
    stepQuantity: array.length,
  });

  return (
    <>
      <ProgressTracker.Root size="large" orientation="horizontal" currentStep={currentStep}>
        <ProgressTracker.Header>
          {array.map((item, index) => (
            <ProgressTracker.Step
              index={index}
              key={item}
              completed={completedSteps.includes(index)}
              onSelect={(indexSelected) => {
                setCompletedSteps([...completedSteps, currentStep]);
                goTo(indexSelected);
              }}
            >
              <ProgressTracker.StepLabel
                alertMessage={`alert error for Step ${index}`}
                label={`Step ${index + 1} item ${item}`}
                detail="Detail"
              />
            </ProgressTracker.Step>
          ))}
        </ProgressTracker.Header>
      </ProgressTracker.Root>
      <Paragraph css={{ marginBottom: 12, marginTop: 12 }} alignment="center">
        Current Step {currentStep + 1}
      </Paragraph>
      <div style={{ display: 'flex', flexDirection: 'row', justifyContent: 'space-evenly' }}>
        <Button
          onClick={() => {
            reset();
            setCompletedSteps([]);
          }}
        >
          Reset
        </Button>
        <Button
          disabled={currentStep === 0}
          onClick={() => {
            setCompletedSteps([...completedSteps, currentStep]);
            goToPrevious();
          }}
        >
          Previous
        </Button>
        <Button
          disabled={currentStep >= array.length}
          onClick={() => {
            setCompletedSteps([...completedSteps, currentStep]);
            goToNext();
          }}
        >
          Next
        </Button>
      </div>
    </>
  );
};
